-- Monitoring is explicitly assigned by the user; existing simulation links remain unchanged.
ALTER TABLE algo_strategy
  ADD COLUMN IF NOT EXISTS alert_enabled TINYINT(1) NOT NULL DEFAULT 1;

-- Activation is switched on AlgoStrategy only; the node flags algo_assetclass.activatable and
-- algo_security.activatable could not be set from the user interface and are removed. A switched-off node keeps its
-- effect on the strategies below it: a standalone node becomes switched-off alerts, a hierarchy node switched-off
-- strategies on itself and, for an asset class, on its securities.
DELIMITER //
CREATE OR REPLACE PROCEDURE DropAlgoNodeActivatable()
BEGIN
  IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'algo_security' AND COLUMN_NAME = 'activatable') THEN
    UPDATE algo_strategy s JOIN algo_rule_strategy r ON r.id_algo_rule_strategy = s.id_algo_rule_strategy
      JOIN algo_security a ON a.id_algo_assetclass_security = r.id_algo_assetclass_security
      SET s.alert_enabled = 0 WHERE a.id_algo_security_parent IS NULL AND a.activatable = 0;
    UPDATE algo_strategy s JOIN algo_rule_strategy r ON r.id_algo_rule_strategy = s.id_algo_rule_strategy
      JOIN algo_security a ON a.id_algo_assetclass_security = r.id_algo_assetclass_security
      SET s.activatable = 0 WHERE a.id_algo_security_parent IS NOT NULL AND a.activatable = 0;
    ALTER TABLE algo_security DROP COLUMN activatable;
  END IF;
  IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'algo_assetclass' AND COLUMN_NAME = 'activatable') THEN
    UPDATE algo_strategy s JOIN algo_rule_strategy r ON r.id_algo_rule_strategy = s.id_algo_rule_strategy
      JOIN algo_assetclass c ON c.id_algo_assetclass_security = r.id_algo_assetclass_security
      SET s.activatable = 0 WHERE c.activatable = 0;
    UPDATE algo_strategy s JOIN algo_rule_strategy r ON r.id_algo_rule_strategy = s.id_algo_rule_strategy
      JOIN algo_security a ON a.id_algo_assetclass_security = r.id_algo_assetclass_security
      JOIN algo_assetclass c ON c.id_algo_assetclass_security = a.id_algo_security_parent
      SET s.activatable = 0 WHERE c.activatable = 0;
    ALTER TABLE algo_assetclass DROP COLUMN activatable;
  END IF;
END //
DELIMITER ;
CALL DropAlgoNodeActivatable();
DROP PROCEDURE IF EXISTS DropAlgoNodeActivatable;

-- A standalone strategy switched off through the former alert tab keeps that switch-off as alert_enabled.
UPDATE algo_strategy s JOIN algo_rule_strategy r ON r.id_algo_rule_strategy = s.id_algo_rule_strategy
  JOIN algo_security a ON a.id_algo_assetclass_security = r.id_algo_assetclass_security
  SET s.alert_enabled = 0 WHERE a.id_algo_security_parent IS NULL AND s.activatable = 0;

-- A simulation environment copies the security accounts of its parent tenant, while the algo hierarchy with its
-- account priorities stays in the parent. The copy remembers its source account so the replay can translate them.
ALTER TABLE securityaccount ADD COLUMN IF NOT EXISTS id_origin_securityaccount INT NULL;

-- An algo asset class groups either by a referenced asset class or by a custom category name. The alternative grouping
-- by category type or special investment instrument was never written by any code path and is removed.
ALTER TABLE algo_assetclass DROP COLUMN IF EXISTS category_type;
ALTER TABLE algo_assetclass DROP COLUMN IF EXISTS spec_invest_instrument;

-- A historical replay freezes the whole strategy hierarchy it was submitted with, names and strategy parameters
-- included, so the environment's run view can still show what the run was based on after the hierarchy was edited.
ALTER TABLE algo_simulation_result ADD COLUMN IF NOT EXISTS hierarchy_snapshot LONGTEXT NULL;

-- An algo asset class always belongs to an AlgoTop; asset classes without a hierarchy were never supported.
ALTER TABLE algo_assetclass MODIFY COLUMN id_algo_assetclass_parent INT NOT NULL;

-- The delivery of an alarm is tracked by delivery_status and the per-channel completion times; notified_at was
-- written on success but never read. V0_37_0 consumed it once to derive delivery_status of existing rows.
ALTER TABLE algo_message_alert DROP COLUMN IF EXISTS notified_at;

-- The alarm is linked to its internal message by the mail_entity row; internal_message_id was never read.
ALTER TABLE algo_message_alert DROP COLUMN IF EXISTS internal_message_id;

-- A crossing is decided by last_side and config_fingerprint alone; the observed value and time were never read.
ALTER TABLE algo_alert_state DROP COLUMN IF EXISTS last_value;
ALTER TABLE algo_alert_state DROP COLUMN IF EXISTS last_evaluated;

-- The cooldown dates are rebuilt from the ledger on every reconciliation; the stored copies were never read.
ALTER TABLE algo_execution_state DROP COLUMN IF EXISTS last_entry;
ALTER TABLE algo_execution_state DROP COLUMN IF EXISTS last_exit;

-- A run's configuration is frozen in hierarchy_snapshot, which carries every level; strategy_snapshot was never read.
ALTER TABLE algo_simulation_result DROP COLUMN IF EXISTS strategy_snapshot;

