-- Completed replays distinguish paid FX markup from missing tariff coverage.
ALTER TABLE algo_simulation_result ADD COLUMN IF NOT EXISTS fx_markup_paid DOUBLE NULL,
  ADD COLUMN IF NOT EXISTS fx_uncovered_conversions INT NULL;

-- The rebalancing report recalculates the plan live, and the alarm takes its figures from the plan in memory, so the
-- stored target and actual values of a recommendation line have no reader. Mean reversion never filled them.
ALTER TABLE algo_recommendation DROP COLUMN IF EXISTS target_percentage, DROP COLUMN IF EXISTS actual_percentage,
  DROP COLUMN IF EXISTS target_amount, DROP COLUMN IF EXISTS actual_amount;

-- Lifetime caps on the shared and user-owned tables that had a daily budget but no ceiling (issue #230), and on the
-- managed clients one advisor may create. owner_scope 2 counts the acting user - by created_by where the table has
-- one, otherwise by its user column; ManagedClient (owner_scope 0) counts the advisor's MANAGE grants. The defaults are
-- ceilings on abuse, several times what the largest creator holds today. No property_name to read a former value
-- from: none of these keys ever existed in globalparameters.
INSERT IGNORE INTO entity_limit (limit_type, entity_name, relation_entity_name, count_scope, owner_scope, limit_value,
  created_by, last_modified_by, last_modified_time, version)
SELECT 0, x.entity_name, x.relation_entity_name, x.count_scope, x.owner_scope, x.default_value,
  0, 0, CURRENT_TIMESTAMP, 0
FROM (SELECT 'GenericConnectorDef' AS entity_name, CAST(NULL AS CHAR(40)) AS relation_entity_name,
        CAST(NULL AS SIGNED) AS count_scope, 2 AS owner_scope, CAST(NULL AS CHAR) AS property_name, 20 AS default_value
      UNION ALL SELECT 'ImportTransactionPlatform', NULL, NULL, 2, NULL,   50
      UNION ALL SELECT 'ImportTransactionTemplate', NULL, NULL, 2, NULL,  300
      UNION ALL SELECT 'TradingCalendarRuleSet',    NULL, NULL, 2, NULL,  200
      UNION ALL SELECT 'TradingPlatformPlan',       NULL, NULL, 2, NULL,  100
      UNION ALL SELECT 'RiskFreeRateMapping',       NULL, NULL, 2, NULL,   50
      UNION ALL SELECT 'UDFMetadataSecurity',       NULL, NULL, 2, NULL,   50
      UNION ALL SELECT 'UDFMetadataGeneral',        NULL, NULL, 2, NULL,   50
      UNION ALL SELECT 'MailSettingForward',        NULL, NULL, 2, NULL,   50
      UNION ALL SELECT 'MailSendRecv',              NULL, NULL, 2, NULL, 2000
      UNION ALL SELECT 'ProposeUserTask',           NULL, NULL, 2, NULL,  100
      UNION ALL SELECT 'ManagedClient',             NULL, NULL, 0, NULL,   20) x;

-- The activation switch of an AlgoTop duplicated the monitoring assignment, which alone decides whether a hierarchy
-- is evaluated in the background, and it silently emptied the mean reversion replay of every hierarchy created before
-- V0.37.0, whose rows still carry 0. A replay evaluates a hierarchy as it is configured, so the flag is removed.
ALTER TABLE algo_top DROP COLUMN IF EXISTS activatable;

-- SECTION-BEGIN bankrupt-security-no-trading-since
-- no_data_since records when the issuer stopped delivering prices and concerns the price maintenance only. Whether an
-- exchange and a broker still let the instrument be traded is a separate fact: an instrument can go on being quoted
-- long after its trading was suspended. no_trading_since is the day from which a historical simulation neither buys
-- nor sells the instrument, generates no further coupon and does not repay it at maturity. The simulation read
-- no_data_since until now, so the existing rows take that date over once, when the column is created. Rallye 3.25
-- 18-24 is still quoted, while its trading has been suspended since 2023-01-09.
DELIMITER //
CREATE OR REPLACE PROCEDURE AddBankruptSecurityNoTradingSince()
BEGIN
  IF NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'bankrupt_security' AND COLUMN_NAME = 'no_trading_since') THEN
    ALTER TABLE bankrupt_security ADD COLUMN no_trading_since DATE DEFAULT NULL AFTER no_data_since;
    UPDATE bankrupt_security SET no_trading_since = no_data_since;
    UPDATE bankrupt_security bs JOIN security s ON s.id_securitycurrency = bs.id_securitycurrency
      SET bs.no_data_since = NULL, bs.no_trading_since = '2023-01-09' WHERE s.isin = 'CH0398013778';
  END IF;
END //
DELIMITER ;
CALL AddBankruptSecurityNoTradingSince();
DROP PROCEDURE IF EXISTS AddBankruptSecurityNoTradingSince;
-- SECTION-END bankrupt-security-no-trading-since
